(()=>{const form=document.querySelector('#contact-form'),email=document.querySelector('#contact-email'),next=document.querySelector('#contact-continue'),first=document.querySelector('#contact-email-step'),second=document.querySelector('#contact-message-step'),message=document.querySelector('#contact-message'),step=document.querySelector('#contact-step');let stage=1;email.addEventListener('input',()=>next.disabled=!email.validity.valid||!email.value.trim());function change(value){stage=value;first.hidden=value!==1;second.hidden=value!==2;message.required=value===2;step.textContent=value+'/2';step.setAttribute('aria-label',`Step ${value} of 2`);(value===2?document.querySelector('#contact-topic'):email).focus()}next.addEventListener('click',()=>{if(email.reportValidity())change(2)});email.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(email.reportValidity())change(2)}});document.querySelector('#contact-back').addEventListener('click',()=>change(1));form.addEventListener('submit',e=>{if(stage===1){e.preventDefault();if(email.reportValidity())change(2)}else if(!email.validity.valid){e.preventDefault();change(1);email.reportValidity()}})})();
